/**
 * Typed Tauri invocation for the transcribe_wav_file command.
 *
 * bindings.ts is auto-generated by tauri-specta on every debug build.
 * Rather than editing that generated file (which gets overwritten) we
 * provide a hand-crafted wrapper here so the store can import it directly.
 */
import { invoke } from "@tauri-apps/api/core";

export type TranscribeResult =
  | { status: "ok"; data: string }
  | { status: "error"; error: string };

/**
 * Transcribes a WAV file (16 kHz mono 16-bit PCM, ≤ 100 MB) with the
 * currently selected model. Returns the transcript, or an error string.
 * Nothing is pasted or saved to history.
 */
export async function transcribeWavFile(
  path: string,
): Promise<TranscribeResult> {
  try {
    const data = await invoke<string>("transcribe_wav_file", { path });
    return { status: "ok", data };
  } catch (e) {
    return { status: "error", error: String(e) };
  }
}
